<!doctype html>
<html lang="pt"><head><meta charset="utf-8"><style>
@page{size:A4 portrait;margin:9mm 11mm 14mm}*{box-sizing:border-box}body{font-family:dejavusans,sans-serif;color:#000;font-size:10pt;margin:0}.report-header{height:29mm;display:grid;grid-template-columns:48mm 1fr 51mm;border:1.5px solid #111;margin-bottom:5mm}.company-logo{display:flex;align-items:center;justify-content:center;border-right:1px solid #777;padding:3mm}.company-logo img{display:block;max-width:41mm;max-height:21mm}.company-name{font-size:15pt;font-weight:bold;letter-spacing:.4px}.report-heading{text-align:center;padding:4mm 2mm}.report-heading h1{font-size:17pt;text-transform:uppercase;margin:0 0 2mm}.order-number{font-size:15pt;font-weight:bold}.barcode-box{border-left:1px solid #777;text-align:center;padding:2.2mm 2mm}.barcode-bars{display:block;height:13mm;white-space:nowrap;overflow:hidden}.barcode-bars i{display:inline-block;height:100%}.barcode-bars .bar{background:#000}.barcode-bars .gap{background:#fff}.barcode-bars .narrow{width:.35mm}.barcode-bars .wide{width:.9mm}.barcode-text{display:block;font-family:monospace;font-size:8pt;font-weight:bold;letter-spacing:1px;margin-top:.5mm}.section{border:1.5px solid #111;margin:0 0 4mm;page-break-inside:avoid}.section-title{font-size:10pt;color:#000;text-align:left;text-transform:uppercase;letter-spacing:.4px;background:#e6e7e8;border-bottom:1px solid #777;padding:2mm 3mm;margin:0}.section-no{display:inline-block;font-weight:bold;margin-right:2mm}.order-grid,.product,.facts,.operations{width:100%;border-collapse:collapse}.order-grid td{width:25%;border-right:1px solid #999;padding:2.5mm 3mm;vertical-align:top}.order-grid td:last-child{border-right:0}.label{display:block;font-size:7.5pt;color:#333;text-transform:uppercase;letter-spacing:.35px;margin-bottom:1mm}.value{font-size:11pt;font-weight:bold;line-height:1.25}.product td{vertical-align:top}.art{width:42%;height:66mm;background:#fff;border-right:1px solid #999;text-align:center;padding:3mm}.art img{max-width:100%;max-height:59mm}.empty{color:#555;padding-top:23mm}.details{padding:2mm 3mm}.article-code{font-size:17pt;font-weight:bold;border-bottom:1px solid #999;padding:0 0 2mm;margin-bottom:2mm}.article-description{font-size:12pt;font-weight:bold;line-height:1.3;border-bottom:1px solid #bbb;padding-bottom:2mm;margin-bottom:2mm;word-wrap:break-word}.facts td{width:50%;padding:2mm;border-bottom:1px solid #ccc;vertical-align:top}.facts tr:last-child td{border-bottom:0}.facts td:first-child{border-right:1px solid #ccc}.features{padding:2.5mm 3mm;font-size:10pt}.features strong{font-size:11pt}.operations th{background:#e6e7e8;border:1px solid #777;font-size:8pt;text-transform:uppercase;text-align:left;padding:2mm}.operations td{border:1px solid #999;padding:3mm 2mm;vertical-align:top;font-size:10pt;height:13mm}.operations .seq{width:10mm;text-align:center}.operations .machine{width:35mm}.operations .time{width:27mm}.operations .status{width:27mm}.instruction{display:block;font-size:9pt;margin-top:1mm;color:#333}.notes{min-height:20mm;padding:3mm;font-size:10pt;line-height:1.4}.document-footer{position:fixed;bottom:-10mm;left:0;right:0;border-top:1px solid #777;padding-top:1.5mm;font-size:7pt;color:#222}.document-footer table{width:100%;border-collapse:collapse}.document-footer td:nth-child(2){text-align:center}.document-footer td:last-child{text-align:right}.muted{color:#555}
</style></head><body>
<footer class="document-footer"><table><tr><td><strong>Documento:</strong> <?=h($productionDossierDocumentNumber)?></td><td><strong>OF:</strong> <?=h($o['order_number'])?></td><td>Emissão <?=date('d/m/Y H:i')?> · GesTisser</td></tr></table></footer>
<header class="report-header"><div class="company-logo"><?php if($productionCompanyLogo!==''):?><img src="<?=h($productionCompanyLogo)?>" alt="<?=h($productionCompanyName)?>"><?php else:?><span class="company-name"><?=h($productionCompanyName)?></span><?php endif;?></div><div class="report-heading"><h1>Folha de Acompanhamento</h1><div class="order-number">OF <?=h($o['order_number'])?></div></div><div class="barcode-box"><?=pd_barcode39_html($o['order_number'])?></div></header>
<section class="section"><h2 class="section-title"><span class="section-no">01</span>Identificação da encomenda e do artigo</h2><table class="order-grid"><tr><td><span class="label">Cliente</span><span class="value"><?=h($o['customer_name']?:'—')?></span></td><td><span class="label">Quantidade planeada</span><span class="value"><?=pd_num($o['planned_quantity'])?></span></td><td><span class="label">Data de entrega</span><span class="value"><?=pd_date($o['due_date']??'')?></span></td><td><span class="label">Encomenda cliente</span><span class="value"><?=h($o['customer_order_reference']??$s['_order']['customer_order']??'—')?></span></td></tr><tr><td><span class="label">N.º prova</span><span class="value"><?=h($s['_order']['proof_number']??'—')?></span></td><td><span class="label">N.º paletes previsto</span><span class="value"><?=h(($s['_order']['planned_pallets']??'')!==''?$s['_order']['planned_pallets']:'—')?></span></td><td><span class="label">Tipo de palete</span><span class="value"><?=h($s['_order']['pallet_type']??'—')?></span></td><td><span class="label">Lote</span><span class="value"><?=h($s['_order']['lot']??'—')?></span></td></tr></table><table class="product"><tr><td class="art"><?php if($mainDocumentThumbnail!==''):?><img src="<?=h($mainDocumentThumbnail)?>" alt="Maqueta do artigo"><?php else:?><div class="empty"><strong>MAQUETA DO ARTIGO</strong><br><?=h($mainDocument['title']??'Sem imagem principal associada')?></div><?php endif;?></td><td class="details"><div class="article-code"><?=h($o['article_code']?:$s['code']??'Artigo não definido')?></div><div class="article-description"><?=h($o['article_description']?:$s['description']??'—')?></div><table class="facts"><?php $articleFacts=['customer_product_code'=>'Referência cliente','material'=>'Material','composition'=>'Composição','width'=>'Largura','length'=>'Comprimento','grammage'=>'Gramagem','theoretical_weight'=>'Peso teórico','printer_roll_measure'=>'Rolo impressor','seam_type'=>'Costura','thread_color'=>'Cor do fio'];$factCells=[];foreach($articleFacts as$key=>$label){$value=trim((string)($s[$key]??''));if($value!=='')$factCells[]=[$label,$value];}foreach(array_chunk($factCells,2)as$row):?><tr><?php foreach($row as$cell):?><td><span class="label"><?=h($cell[0])?></span><span class="value"><?=h($cell[1])?></span></td><?php endforeach;?><?php if(count($row)<2):?><td></td><?php endif;?></tr><?php endforeach;?></table></td></tr></table></section>
<section class="section"><h2 class="section-title"><span class="section-no">02</span>Características e embalagem</h2><div class="features"><strong>Características:</strong> <?php $enabled=[];foreach(['microperforation'=>'Microperfuração','has_gusset'=>'Fole','centered_gusset'=>'Fole centrado','has_handle'=>'Asa','has_holes'=>'Furo']as$key=>$label)if(!empty($s[$key]))$enabled[]=$label;echo h($enabled?implode(' · ',$enabled):'Nenhuma característica especial.');?></div><table class="order-grid"><tr><td><span class="label">Medida do fole</span><span class="value"><?=h($s['gusset_length']??'—')?></span></td><td><span class="label">Perfuração</span><span class="value"><?=h($s['perforation_type']??'—')?></span></td><td><span class="label">Configuração da palete</span><span class="value"><?=h($s['pallet_dimensions']??'—')?></span></td><td><span class="label">Acabamento</span><span class="value"><?=h(implode(' · ',array_filter([$s['pallet_lid']??'',$s['pallet_film']??'',$s['pallet_straps']??'']))?:'—')?></span></td></tr></table></section>
<section class="section"><h2 class="section-title"><span class="section-no">03</span>Registo de produção</h2><table class="operations"><tr><th class="seq">Seq.</th><th>Operação / instrução</th><th class="machine">Máquina</th><th class="time">Previsto</th><th class="status">Estado</th></tr><?php foreach($d['operations']as$op):?><tr><td class="seq"><?=h($op['sequence_no'])?></td><td><strong><?=h($op['name'])?></strong><?php if(trim((string)($op['instructions']??''))!==''):?><span class="instruction"><?=h($op['instructions'])?></span><?php endif;?></td><td><?=h($op['machine_name']?:'—')?></td><td><?=pd_time($op['planned_minutes'])?></td><td><?=h($op['status'])?></td></tr><?php endforeach;?><?php if(!$d['operations']):?><tr><td colspan="5" class="muted">Esta OF ainda não tem operações no routing.</td></tr><?php endif;?></table></section>
<section class="section"><h2 class="section-title"><span class="section-no">04</span>Cores a imprimir — Ordem de Fabrico</h2><table class="order-grid"><tr><td colspan="2"><span class="label">Frente</span><span class="value"><?=h($productionOrderFrontColors?implode(' · ',$productionOrderFrontColors):'—')?></span></td><td colspan="2"><span class="label">Verso</span><span class="value"><?=h($productionOrderBackColors?implode(' · ',$productionOrderBackColors):'—')?></span></td></tr></table></section>
<section class="section"><h2 class="section-title"><span class="section-no">05</span>Observações do operador</h2><div class="notes"><?=nl2br(h(trim((string)($o['notes']??''))?:'Sem observações registadas.'))?></div></section>
